BEGIN;
CREATE TABLE IF NOT EXISTS workflow.closing_rejection(rejection_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),closing_id uuid NOT NULL REFERENCES workflow.closing_period(closing_id),rejected_by text NOT NULL,comment text NOT NULL CHECK(length(trim(comment))>=10),idempotency_key text NOT NULL UNIQUE,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE OR REPLACE FUNCTION workflow.enforce_closing_actor_separation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.resource_type='ClosingPeriod' AND NEW.action IN('APPROVE_CLOSING','REJECT_CLOSING') AND EXISTS(SELECT 1 FROM workflow.closing_period c WHERE c.closing_id::text=NEW.resource_id AND c.requested_by=NEW.actor_id)THEN RAISE EXCEPTION 'Maker cannot approve or reject their own closing';END IF;RETURN NEW;END;$$;
DROP TRIGGER IF EXISTS closing_actor_separation ON workflow.approval_action;CREATE TRIGGER closing_actor_separation BEFORE INSERT ON workflow.approval_action FOR EACH ROW EXECUTE FUNCTION workflow.enforce_closing_actor_separation();
CREATE OR REPLACE FUNCTION workflow.guard_closing_rejection()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF TG_OP='DELETE'OR TG_OP='UPDATE'THEN RAISE EXCEPTION 'Closing rejection evidence is immutable';END IF;IF EXISTS(SELECT 1 FROM workflow.closing_period c WHERE c.closing_id=NEW.closing_id AND c.requested_by=NEW.rejected_by)THEN RAISE EXCEPTION 'Maker cannot reject their own closing';END IF;RETURN NEW;END;$$;
DROP TRIGGER IF EXISTS closing_rejection_guard ON workflow.closing_rejection;CREATE TRIGGER closing_rejection_guard BEFORE INSERT OR UPDATE OR DELETE ON workflow.closing_rejection FOR EACH ROW EXECUTE FUNCTION workflow.guard_closing_rejection();
COMMIT;
